questionvariables.text:
/* ---- Fixed square window [-A,A]^2 on a square board => equal aspect. --------
   Design a cubic with a SMALL leading coefficient so its full detail (two turning
   points and the inflection) shows inside the window before it exits top/bottom:
     f(x) = aa*(x-hh)^3 + pp*(x-hh) + kk,  turning points at hh +/- sqrt(-pp/(3 aa))
   (so pp and aa must have opposite signs). Enumerate the admissible tuples and
   pick one (no generate-and-hope): small |aa|; both turning points and P well
   inside the window; |f'(x0)| in [0.6, 3.2]; P not the inflection, not the origin.
   The tangent slope m0 = f'(x0) may be a simple fraction - fine for a read-off. */
A : 8;

cands : sublist(
  create_list([aa0,pp0,hh0,kk0,xx0],
      aa0, [-1/4,-1/5,-3/20,3/20,1/5,1/4],
      pp0, [-4,-3,-2,-1,1,2,3,4],
      hh0, [-1,0,1],
      kk0, [-2,-1,0,1,2],
      xx0, [-3,-2,-1,0,1,2,3]),
  lambda([z], block(
    [aa:z[1], pp:z[2], hh:z[3], kk:z[4], xv:z[5], dsc, tp, mm, yy, fpp0, tpv1, tpv2],
    dsc : -pp/(3*aa),
    if is(dsc <= 0) then return(false),          /* need real turning points */
    tp   : sqrt(float(dsc)),
    mm   : 3*aa*(xv-hh)^2 + pp,                  /* f'(x0) */
    yy   : aa*(xv-hh)^3 + pp*(xv-hh) + kk,       /* f(x0) */
    fpp0 : 6*aa*(xv-hh),                         /* f''(x0): curvature at P */
    tpv1 : aa*tp^3 + pp*tp + kk,                 /* turning-point y-values */
    tpv2 : -aa*tp^3 - pp*tp + kk,
    is( xv # hh
        and abs(float(hh+tp)) <= 6.5 and abs(float(hh-tp)) <= 6.5
        and abs(float(tpv1)) <= 7 and abs(float(tpv2)) <= 7
        and abs(float(mm)) >= 0.6 and abs(float(mm)) <= 3.2
        and abs(float(yy)) <= 5.5 and abs(float(fpp0)) >= 0.5
        and (xv # 0 or yy # 0) ) )));            /* P is never the origin */

pick : rand(cands);
aa : pick[1];  pp : pick[2];  hh : pick[3];  kk : pick[4];  x0 : pick[5];

f(xx) := aa*(xx-hh)^3 + pp*(xx-hh) + kk;
m0 : 3*aa*(x0-hh)^2 + pp;         /* f'(x0): the target tangent slope */
y0 : f(x0);                       /* P = (x0, y0) */
fpoly : expand(f(x));             /* standard form, for the worked solution */
tanline : expand(y0 + m0*(x - x0));

/* Fixed square window; its (constant) height normalises the through-tolerance. */
bxlo : -A;  bxhi : A;  ylo : -A;  yhi : A;
yspan : 2*A;

/* Initial draggable points: a horizontal line below P (clearly not the tangent). */
Aix : x0 - 3;  Aiy : y0 - 2.5;
Bix : x0 + 3;  Biy : y0 - 2.5;

/* Model answer + question-test helper points (here so <qtest> can see them). */
tqA : float([x0, y0]);
tqB : float([x0 + 2, y0 + 2*m0]);
secB : ev(float([x0 + 2, y0 + 2*(m0 + 4)]), simp);      /* through P, slope m0+4 (wrong, never the normal) */
wpA  : ev(float([x0,     y0 + 0.2*yspan]), simp);       /* right slope, misses P */
wpB  : ev(float([x0 + 2, y0 + 0.2*yspan + 2*m0]), simp);
nmB  : ev(float([x0 + 2, y0 + 2*(-1/m0)]), simp);       /* normal through P */
verB : float([x0, y0 + 3]);                             /* vertical */

feedbackvariables.text:
/* Read the two dragged points. */
ax : ans1[1];  ay : ans1[2];
bx : ans2[1];  by : ans2[2];
dxs : bx - ax;
/* Student's line slope, guarded against a (near-)vertical line. */
sm : if abs(dxs) > 0.05 then (by - ay)/dxs else 1000;
/* Value of the student's line at x0, and the through-point residual at P. */
syx0 : if abs(dxs) > 0.05 then ay + sm*(x0 - ax) else 1000;
thr  : syx0 - y0;
thr_n : thr / yspan;                 /* through-point residual, normalised by board height */
nm : -1/m0;                          /* normal slope, for the diagnostic */
